UPDATE `pass_bar_settings`
SET `definition_json` = '{"effectiveCloses":{"required":30,"horizonDays":30,"rule":"Same-coin signals must be at least one full 30-day outcome horizon apart; cross-coin dependence is disclosed, not removed. Raw rows never count."},"expectancy":{"costBps":18,"bootstrapConfidence":0.95,"bootstrapDraws":2000,"rule":"The paired-bootstrap 95% lower bound of issued average net R minus the dumb-screen buy-and-hold baseline must be above zero. Hit rate is reported only."},"baselines":[{"key":"buyHold","label":"Buy-and-hold","definition":"Always-long asset return from the signal entry to that call''s resolved exit, divided by the signal''s initial risk, on the same date and net of 18 bps."},{"key":"randomEntry","label":"Seeded random-entry","definition":"A deterministically seeded long-or-short call at the same entry with the identical initial-risk stop and 1.5R target, the same 30-day first-touch rule, and 18 bps costs."},{"key":"btcBeta","label":"Always-long BTC beta","definition":"Ex-ante asset beta (minimum 30 aligned prior daily returns) times always-long BTC return over the issued call''s resolved dates, divided by the signal''s initial-risk percentage and net of 18 bps."}],"silence":"Independence-adjusted suppressed candidates, graded with the same 30-day first-touch rule and 18 bps costs, must not have higher average net R than issued calls.","directionSplit":true,"regime":"Each 30-effective-close certification window must include at least one completed UTC Monday–Sunday BTC-up week and one BTC-down-or-flat week, classified by first-to-last BTC close in that week.","funding":{"minimumRecordedDays":30,"rule":"Funding is UNVERIFIED and excluded until 30 distinct days of realized payment R are recorded. At that point recorded funding is included automatically and the bar re-runs; a pre-funding result never authorizes sizing."},"firstTouch":"Within the next 30 owned daily OHLC bars, the first target or invalidation touch closes the call. If both touch in one candle, invalidation wins. If neither touches, the 30th close settles it.","ambiguity":"Target and invalidation in the same candle equals invalidation (pessimistic). Missing OHLC cannot be graded and never counts.","weeksAndFutility":{"futilityAt":15,"rule":"At 15 effective closes in a certification cycle, if the bootstrap 95% upper bound of average net R is below zero, status is futility — reassess."},"recertification":{"everyNewEffectiveCloses":30,"rule":"The latest completed non-overlapping block of 30 effective closes is certified. Every new block replaces the prior certificate; passes are not permanent."},"sizing":"No sizing changes until a funding-included pass. Mixed, futility, bull-regime only, regime-incomplete, and pre-funding pass keep sizing flat."}'
WHERE `version` = 'v1-final';
